def check_coloring(grid_size):
    """
    Checks if the coloring C(x, y) = (x + 2y) mod 4 is valid on a grid.
    A coloring is valid if no two distinct neighboring points share the same color.
    Neighbors include diagonal points (King's move).
    """

    grid_size = grid_size

    # Iterate over all points (x, y) in the grid
    for x in range(-grid_size, grid_size + 1):
        for y in range(-grid_size, grid_size + 1):
            color = (x + 2 * y) % 4

            # Check all 8 neighbors (a, b)
            for dx in [-1, 0, 1]:
                for dy in [-1, 0, 1]:
                    if dx == 0 and dy == 0:
                        continue

                    a, b = x + dx, y + dy

                    # Ensure the neighbor is within the grid bounds (though for a small test grid, this isn't critical)
                    if abs(a) <= grid_size and abs(b) <= grid_size:
                        neighbor_color = (a + 2 * b) % 4

                        if color == neighbor_color:
                            print(f"Conflict found at point ({x}, {y}) and neighbor ({a}, {b}).")
                            print(f"Color for both is {color}.")
                            return False

    return True

# Test on grid [-3, 3] x [-3, 3]
grid_bound = 3
is_valid = check_coloring(grid_bound)

if is_valid:
    print("The coloring C(x, y) = (x + 2y) mod 4 is valid on the tested grid.")
else:
    print("The coloring C(x, y) = (x + 2y) mod 4 is INVALID.")

